{
  "application": "codelang-detect",
  "goal": "Make me a small zero-dependency Python tool that guesses the programming language of a code snippet without loading a model or using the network. I want both a callable library and a CLI that reads a UTF-8 file or piped text and prints the detected lowercase file extension, with unknown for empty input, whitespace or ordinary prose with no convincing code markers. Use a configurable set of weighted regex rules so stronger evidence wins rather than just the first matching language, support a documented starter set of common languages, and make ties deterministic. The CLI should give useful errors and a nonzero exit code when it cannot read its input without dumping a traceback in normal use. Include a few clear examples and install/run instructions, keep the code easy to extend, and don't promise perfect detection of inherently ambiguous snippets or tune the tests to a huge hidden benchmark.",
  "tasks": [
    {
      "id": "language-basic",
      "title": "Specify unknown-input behavior and the initial Python/JavaScript detection contract.",
      "depends_on": [],
      "implementation_files": [
        "codelang_detect/__init__.py",
        "codelang_detect/detector.py"
      ],
      "target_file": "tests/test_detection_basics.py",
      "acceptance": [
        "Empty, whitespace and ordinary prose return unknown.",
        "Clear Python and JavaScript snippets return py and js respectively."
      ]
    },
    {
      "id": "language-rules",
      "title": "Specify weighted rules, deterministic ties and live configuration replacement.",
      "depends_on": [
        "language-basic"
      ],
      "implementation_files": [
        "codelang_detect/detector.py"
      ],
      "target_file": "tests/test_detection_rules.py",
      "acceptance": [
        "Weight 3 beats two matching weight-1 rules.",
        "Equal scores choose declaration order, even when alphabetical order differs.",
        "A single positive score qualifies; zero evidence remains unknown.",
        "Replacing the public configuration between calls immediately changes the result."
      ]
    },
    {
      "id": "language-cli-success",
      "title": "Specify CLI input routes and exact successful output.",
      "depends_on": [
        "language-basic"
      ],
      "implementation_files": [
        "codelang_detect/cli.py"
      ],
      "target_file": "tests/test_cli_success.py",
      "acceptance": [
        "A Python snippet inside a .txt file is identified from its contents.",
        "Piped text is accepted when no file argument exists.",
        "Successful output has exactly one label/newline and no stderr."
      ]
    },
    {
      "id": "language-cli-errors",
      "title": "Specify CLI failure classes and useful diagnostics.",
      "depends_on": [
        "language-cli-success"
      ],
      "implementation_files": [
        "codelang_detect/cli.py"
      ],
      "target_file": "tests/test_cli_errors.py",
      "acceptance": [
        "Missing files produce usage exit 2 with useful stderr and empty stdout.",
        "Closed stdin and invalid UTF-8 produce processing exit 1.",
        "Normal input errors do not print tracebacks."
      ]
    },
    {
      "id": "language-delivery",
      "title": "Package the CLI and document examples and installation.",
      "depends_on": [
        "language-cli-success",
        "language-cli-errors"
      ],
      "implementation_files": [
        "pyproject.toml",
        "README.md"
      ],
      "target_file": "tests/test_packaged_cli.py",
      "acceptance": [
        "Verify installation and documented examples in a clean environment.",
        "Explicitly document starter languages and ambiguous-snippet limitations."
      ],
      "demonstration_available": false
    }
  ],
  "unresolved": [
    "Additional language targets, installation examples and ambiguous-snippet accuracy remain manual/future work."
  ],
  "context_policy": "Interfaces are agreed; implementations may not exist yet. No completion or tool execution is implied."
}

{
  "application": "llm-bender-lab",
  "goal": "Make me a practical Python lab for running small language-model fine-tuning experiments reproducibly. I want to define an experiment, validate conversational training data and its train/evaluation separation, save the resolved configuration, run a short training smoke through a replaceable trainer, save its adapter and metadata, evaluate the starting model and candidate under matched settings, and get a readable before/after summary. A malformed dataset or overlapping held-out examples should stop preflight rather than quietly train. Keep experiment runs in separate directories, preserve older outputs, and record model/data revisions, seed, code identity and effective settings so I can tell what actually ran. If a run fails, retain its logs and status without claiming success. Do not require a GPU, download weights or start real training when I run the lab's own tests: use a tiny fake trainer/evaluator there, but make the workflow ready to connect to a real backend. Keep credentials and large weights out of manifests and Git, distinguish unavailable metrics from zeros, and give me simple commands for preparing, running and comparing one experiment.",
  "tasks": [
    {
      "id": "experiment-preflight",
      "title": "Specify conversation/split validation before any backend is invoked.",
      "depends_on": [],
      "implementation_files": [
        "experiment_workflow.py"
      ],
      "target_file": "tests/test_experiment_preflight.py",
      "acceptance": [
        "Reject empty messages, wrong roles, unknown splits and normalized overlapping prompts.",
        "The trainer is never invoked after invalid preflight."
      ]
    },
    {
      "id": "experiment-matched-evaluation",
      "title": "Specify train/test routing and reproducible matched model comparisons.",
      "depends_on": [],
      "implementation_files": [
        "experiment_workflow.py"
      ],
      "target_file": "tests/test_experiment_matched_evaluation.py",
      "acceptance": [
        "Trainer receives only training rows and evaluator only test rows.",
        "Baseline identity is the model revision and candidate identity the adapter path.",
        "Preserve resolved config, adapter and completed status.",
        "Report real deltas and unavailable metrics without replacing missingness with zero."
      ]
    },
    {
      "id": "experiment-artifact-isolation",
      "title": "Specify immutable previous runs and faithful zero-valued metrics.",
      "depends_on": [],
      "implementation_files": [
        "experiment_workflow.py"
      ],
      "target_file": "tests/test_experiment_artifact_isolation.py",
      "acceptance": [
        "Reject an existing run directory.",
        "A distinct run succeeds without modifying any previous file bytes.",
        "A real 0.0 metric remains before=after=delta=0.0."
      ]
    },
    {
      "id": "experiment-failure-reporting",
      "title": "Specify explicit failed status and secret-free returned and saved errors.",
      "depends_on": [],
      "implementation_files": [
        "experiment_workflow.py"
      ],
      "target_file": "tests/test_experiment_failure_reporting.py",
      "acceptance": [
        "Backend failure yields failed status, useful diagnostics and no success summary.",
        "Configured secret values are absent from returned errors and every saved text artifact."
      ]
    },
    {
      "id": "llm-bender-lab-delivery",
      "title": "Verify documented delivery and live UI/backend integration separately.",
      "depends_on": [],
      "implementation_files": [
        "README.md"
      ],
      "target_file": "tests/test_delivery.py",
      "acceptance": [
        "Real training backend integration, credential publishing policy and actual CLI delivery remain separate checks."
      ],
      "demonstration_available": false
    }
  ],
  "unresolved": [
    "Real training backend integration, credential publishing policy and actual CLI delivery remain separate checks."
  ],
  "context_policy": "Interfaces are agreed; implementations may not exist yet. No completion or tool execution is implied."
}

{
  "application": "miniature-llms",
  "goal": "Build me a small educational Python repository of working language-model components that I can run on CPU with tiny tensors and understand from the code. For the first complete version, include token embeddings, rotary position encoding, RMS normalization, a causal attention block, a feed-forward block and a tiny next-token model that composes them. Use PyTorch, keep tensors consistently batch-by-sequence-by-hidden dimension at public boundaries, make weights and dimensions configurable, and explain the role of each component without claiming this tiny model reproduces a frontier model's capability. I want numerical examples that check more than output shape, a demonstration that later tokens cannot influence earlier causal outputs, proper gradients, and saving/reloading weights without changing predictions. Include a short deterministic training demo on a tiny fixed local corpus and a generation command, with no model downloads or GPU requirement. Reject incompatible dimensions clearly and keep the implementation modular enough that I can later add other architectures; JAX, custom kernels and every advanced architecture can wait.",
  "tasks": [
    {
      "id": "tensor-rms-normalization",
      "title": "Specify RMS normalization scale, epsilon and numeric gradients.",
      "depends_on": [],
      "implementation_files": [
        "_7_RMSNorm/pytorch.py"
      ],
      "target_file": "tests/test_tensor_rms_normalization.py",
      "acceptance": [
        "Normalize the last dimension by sqrt(mean(x squared)+epsilon), then learned scale.",
        "Positive epsilon maps zero inputs to finite zeros.",
        "Scale gradients agree with the explicit [3,4]/sqrt(12.5) fixture."
      ]
    },
    {
      "id": "tensor-rotary-positions",
      "title": "Specify rotary half-rotation, sequence positions and dimension errors.",
      "depends_on": [],
      "implementation_files": [
        "_4_RoPE/pytorch.py"
      ],
      "target_file": "tests/test_tensor_rotary_positions.py",
      "acceptance": [
        "rotate_half negates the second half and concatenates the first.",
        "Position zero is identity on every head.",
        "Position one rotates along sequence rather than head axes.",
        "Reject odd or mismatched head dimensions with the declared diagnostics."
      ]
    },
    {
      "id": "tensor-model-composition",
      "title": "Specify composed logits, trainable gradients and incompatible dimensions.",
      "depends_on": [],
      "implementation_files": [
        "tiny_model.py"
      ],
      "target_file": "tests/test_tensor_model_composition.py",
      "acceptance": [
        "Return [batch,sequence,vocab] logits.",
        "All trainable parameters have finite gradients and some gradient is nonzero.",
        "Reject indivisible hidden sizes and odd per-head dimensions."
      ]
    },
    {
      "id": "tensor-causal-independence",
      "title": "Specify causal invariance and sensitivity for the composed model.",
      "depends_on": [],
      "implementation_files": [
        "tiny_model.py"
      ],
      "target_file": "tests/test_tensor_causal_independence.py",
      "acceptance": [
        "Changing future tokens cannot alter earlier logits.",
        "Later logits must still respond to changed input."
      ]
    },
    {
      "id": "tensor-checkpoint-roundtrip",
      "title": "Specify configuration/weight checkpoint preservation.",
      "depends_on": [],
      "implementation_files": [
        "tiny_model.py"
      ],
      "target_file": "tests/test_tensor_checkpoint_roundtrip.py",
      "acceptance": [
        "Saving and loading reconstructs the same CPU model configuration and weights.",
        "Eval logits match exactly at the same runtime."
      ]
    },
    {
      "id": "tensor-training-generation",
      "title": "Specify deterministic tiny CPU training and actual greedy next-token decoding.",
      "depends_on": [],
      "implementation_files": [
        "tiny_model.py"
      ],
      "target_file": "tests/test_tensor_training_generation.py",
      "acceptance": [
        "Repeat the same seed and fixture to get identical finite loss histories.",
        "The bounded smoke loss improves; no claim of general language capability.",
        "Use last-position logit maxima, preserve prompt, honor zero/positive budgets and reject negative budgets."
      ]
    },
    {
      "id": "miniature-llms-delivery",
      "title": "Verify documented delivery and live UI/backend integration separately.",
      "depends_on": [],
      "implementation_files": [
        "README.md"
      ],
      "target_file": "tests/test_delivery.py",
      "acceptance": [
        "Standalone architecture documentation and actual CLI integration remain separate checks; do not treat PyTorch/JAX variants as independent behaviors."
      ],
      "demonstration_available": false
    }
  ],
  "unresolved": [
    "Standalone architecture documentation and actual CLI integration remain separate checks; do not treat PyTorch/JAX variants as independent behaviors."
  ],
  "context_policy": "Interfaces are agreed; implementations may not exist yet. No completion or tool execution is implied."
}

{
  "application": "repo-context",
  "goal": "Build me a Python tool that turns a GitHub repository into a readable Markdown context snapshot I can give an LLM. Let me supply a repository URL, optionally a branch and subfolder, choose file extensions and a per-file line limit, and get repository metadata, dependency summaries, a directory tree and selected text-file contents in deterministic order. Respect .gitignore and common generated/dependency directories, don't include secret environment files by default, skip non-text files, and clearly identify truncated files instead of making the snapshot look complete. Support private repositories with a token kept out of the output, show a useful error when cloning or reading fails, and clean up temporary checkouts even after failure. Give me a CLI and a simple local Streamlit page for generating and downloading the same snapshot; no hosted service is necessary. Keep the core independent of the UI so it can be checked with a small local fixture repository instead of real network requests.",
  "tasks": [
    {
      "id": "snapshot-file-tree",
      "title": "Specify extension and ignore filtering in a deterministic file tree.",
      "depends_on": [],
      "implementation_files": [
        "repo_context/core.py"
      ],
      "target_file": "tests/test_snapshot_file_tree.py",
      "acceptance": [
        "Show selected .py files and the declared root label.",
        "Exclude other extensions, node_modules and caller-ignored files.",
        "An entirely ignored tree contains only the root line."
      ]
    },
    {
      "id": "snapshot-dependencies",
      "title": "Specify dependency summaries from requirements and project metadata.",
      "depends_on": [],
      "implementation_files": [
        "repo_context/core.py"
      ],
      "target_file": "tests/test_snapshot_dependencies.py",
      "acceptance": [
        "Recognize Python from requirements.txt and pyproject.toml.",
        "Include the source filename and dependency entries.",
        "Formatting whitespace is not part of the contract."
      ]
    },
    {
      "id": "snapshot-url-routing",
      "title": "Specify repository, branch and subfolder extraction from simple GitHub URLs.",
      "depends_on": [],
      "implementation_files": [
        "repo_context/core.py"
      ],
      "target_file": "tests/test_snapshot_url_routing.py",
      "acceptance": [
        "Normalize the repository to a canonical .git URL.",
        "Preserve simple branch names and nested subfolder paths.",
        "Do not guess slash-containing branch semantics."
      ]
    },
    {
      "id": "snapshot-text-decoding",
      "title": "Specify UTF-8 text recognition with invalid-byte controls.",
      "depends_on": [],
      "implementation_files": [
        "repo_context/core.py"
      ],
      "target_file": "tests/test_snapshot_text_decoding.py",
      "acceptance": [
        "Valid Turkish UTF-8 text is recognized.",
        "Invalid UTF-8 bytes are rejected."
      ]
    },
    {
      "id": "snapshot-safe-context",
      "title": "Specify scoped snapshots, sorted content, truncation, secret exclusion and cleanup.",
      "depends_on": [],
      "implementation_files": [
        "context_workflow.py"
      ],
      "target_file": "tests/test_snapshot_safe_context.py",
      "acceptance": [
        "Preserve branch/subfolder and honor the public clone injection contract.",
        "Respect .gitignore, extension, symlink and dependency-directory exclusions.",
        "Show truncation and deterministic multi-file order without leaking tokens.",
        "Owned checkouts are deleted after successful snapshot creation."
      ]
    },
    {
      "id": "snapshot-controller-routing",
      "title": "Specify shared CLI/UI behavior and invalid-URL rejection before cloning.",
      "depends_on": [],
      "implementation_files": [
        "context_workflow.py"
      ],
      "target_file": "tests/test_snapshot_controller_routing.py",
      "acceptance": [
        "CLI and UI wrappers invoke the same operation with identical arguments.",
        "A non-HTTPS GitHub URL fails before clone is called."
      ]
    },
    {
      "id": "repo-context-delivery",
      "title": "Verify documented delivery and live UI/backend integration separately.",
      "depends_on": [],
      "implementation_files": [
        "README.md"
      ],
      "target_file": "tests/test_delivery.py",
      "acceptance": [
        "Actual CLI/Streamlit event wiring and private authentication remain manual checks. Slash-containing branch names remain unresolved."
      ],
      "demonstration_available": false
    }
  ],
  "unresolved": [
    "Actual CLI/Streamlit event wiring and private authentication remain manual checks. Slash-containing branch names remain unresolved."
  ],
  "context_policy": "Interfaces are agreed; implementations may not exist yet. No completion or tool execution is implied."
}
